/**
 * Whether a Fastify error response should be reported to Sentry.
 * Uses SDK init state (not env presence) so hardcoded DSN fallbacks still report.
 */
export function shouldReportServerError(
  statusCode: number,
  sentryInitialized: boolean
): boolean {
  return statusCode >= 500 && sentryInitialized;
}

import { describe, expect, it } from 'vitest';
import { shouldReportServerError } from '../sentry-capture.js';

describe('shouldReportServerError', () => {
  it('reports 500+ only when Sentry is initialized', () => {
    expect(shouldReportServerError(500, true)).toBe(true);
    expect(shouldReportServerError(503, true)).toBe(true);
    expect(shouldReportServerError(500, false)).toBe(false);
  });

  it('never reports client errors', () => {
    expect(shouldReportServerError(400, true)).toBe(false);
    expect(shouldReportServerError(404, true)).toBe(false);
    expect(shouldReportServerError(499, true)).toBe(false);
  });
});

import { describe, expect, it } from 'vitest';
import { resolveSentryRelease } from '../sentry-release.js';

describe('resolveSentryRelease', () => {
  it('returns the first non-blank candidate', () => {
    expect(resolveSentryRelease(undefined, '  ', 'abc123', 'other')).toBe('abc123');
    expect(resolveSentryRelease('v1.2.3', 'abc123')).toBe('v1.2.3');
  });

  it('returns undefined when nothing usable is set', () => {
    expect(resolveSentryRelease()).toBeUndefined();
    expect(resolveSentryRelease('', '   ', undefined)).toBeUndefined();
  });
});

